-- Column and table comments (read by NocoDB, TablePlus, DBeaver and psql \d+),
-- then the updated_at trigger on every operating-model table, then the
-- booking_travellers same-family trigger. Metadata and triggers only: no row
-- or column of an existing table changes. Source text: docs/data-model.md.
COMMENT ON TABLE "departures" IS 'One dated run of a journey, e.g. San Sebastián 10–19 July 2027. Holds the capacity, the minimum needed to run, and the go/no-go fact (guaranteed_at). Bookings, service lines, documents and interactions hang off it. The existing journey enum is reused in place of a separate trips table.';--> statement-breakpoint
COMMENT ON COLUMN "departures"."id" IS 'Primary key.';--> statement-breakpoint
COMMENT ON COLUMN "departures"."code" IS 'Short human code, unique, e.g. ''SSB-2027-07'', ''ANT-2027-08''. Used in emails, Stripe metadata and vendor messages.';--> statement-breakpoint
COMMENT ON COLUMN "departures"."journey" IS 'Which journey this runs (san-sebastian, antigua). Same enum as reservations.journey, so a deposit resolves to its departure while each journey has one departure.';--> statement-breakpoint
COMMENT ON COLUMN "departures"."name" IS 'Display name, e.g. ''San Sebastián, July 2027''. NocoDB''s display value.';--> statement-breakpoint
COMMENT ON COLUMN "departures"."starts_on" IS 'First day, local date at the destination.';--> statement-breakpoint
COMMENT ON COLUMN "departures"."ends_on" IS 'Last day, local date. Must be after starts_on.';--> statement-breakpoint
COMMENT ON COLUMN "departures"."status" IS 'Sales lifecycle: planning, open, closed, completed, cancelled. ''Full'' is derived from bookings, not stored.';--> statement-breakpoint
COMMENT ON COLUMN "departures"."min_families" IS 'Families needed for the departure to run.';--> statement-breakpoint
COMMENT ON COLUMN "departures"."max_families" IS 'Capacity in families.';--> statement-breakpoint
COMMENT ON COLUMN "departures"."guaranteed_at" IS 'When Jesse declared that it will run (minimum reached or underwritten). NULL = not yet guaranteed. Kept separate from status because a departure can be guaranteed and still open.';--> statement-breakpoint
COMMENT ON COLUMN "departures"."currency" IS 'Currency families are charged in. Lowercase ISO 4217, as Stripe and reservations.currency use.';--> statement-breakpoint
COMMENT ON COLUMN "departures"."balance_due_on" IS 'Default due date for the final balance, used when building a booking''s payments rows (e.g. 90 days before starts_on).';--> statement-breakpoint
COMMENT ON COLUMN "departures"."price_note" IS 'Pricing in words while the pricing model is unsettled, e.g. ''from $X per family of four''. The agreed price is bookings.total_price_cents.';--> statement-breakpoint
COMMENT ON COLUMN "departures"."notes" IS 'Planning notes. No health details and no children''s names.';--> statement-breakpoint
COMMENT ON COLUMN "departures"."created_at" IS 'Row creation time.';--> statement-breakpoint
COMMENT ON COLUMN "departures"."updated_at" IS 'Last change. Kept current by the set_updated_at trigger, so NocoDB edits update it too.';--> statement-breakpoint
COMMENT ON TABLE "families" IS 'The customer: one row per household Avelune is talking to or travelling with. Usually promoted by hand from an early-access signup. The signup row stays as the marketing-consent record; the family is the operational customer. The primary contact''s details live here, so there is no separate contacts table for customers.';--> statement-breakpoint
COMMENT ON COLUMN "families"."id" IS 'Primary key.';--> statement-breakpoint
COMMENT ON COLUMN "families"."signup_id" IS 'The early-access signup this family came from, if any (unique). SET NULL means honouring a deletion request on the signup does not erase a live booking.';--> statement-breakpoint
COMMENT ON COLUMN "families"."family_name" IS 'How we refer to the household, e.g. ''The Ortiz family''.';--> statement-breakpoint
COMMENT ON COLUMN "families"."primary_contact_name" IS 'Name of the adult who books and pays. Only a first name until the booking-stage privacy notice is live (that is all the signup collects).';--> statement-breakpoint
COMMENT ON COLUMN "families"."email" IS 'Primary contact email, as typed, trimmed.';--> statement-breakpoint
COMMENT ON COLUMN "families"."email_key" IS 'Dedupe key (unique). Generated by the database with the same rule as signups.email_key, so it can never drift and nobody types it in NocoDB. Read-only.';--> statement-breakpoint
COMMENT ON COLUMN "families"."phone" IS 'BOOKING STAGE: collect only after the privacy page is updated. Mobile in E.164 (e.g. +14155550123), for trip-week WhatsApp/SMS.';--> statement-breakpoint
COMMENT ON COLUMN "families"."home_city" IS 'BOOKING STAGE: collect only after the privacy page is updated. City and state, e.g. ''Austin, TX'', for flights and time zones. No street address.';--> statement-breakpoint
COMMENT ON COLUMN "families"."country_code" IS 'Country of residence, ISO 3166-1 alpha-2, uppercase.';--> statement-breakpoint
COMMENT ON COLUMN "families"."status" IS 'Hand-set pipeline stage: lead, in_conversation, booked, travelled, inactive. A judgement for filtering, not derived from bookings.';--> statement-breakpoint
COMMENT ON COLUMN "families"."source" IS 'How they found Avelune, free text, e.g. ''early_access'', ''referral: Lopez family''.';--> statement-breakpoint
COMMENT ON COLUMN "families"."stripe_customer_id" IS 'Stripe Customer (cus_...), unique, copied from the first paid reservation, so deposit, instalment invoices and refunds sit on one Stripe customer.';--> statement-breakpoint
COMMENT ON COLUMN "families"."notes" IS 'Standing notes (who decides, preferences, tone). Dated events go in interactions. Never record health details, children''s names or passport numbers here.';--> statement-breakpoint
COMMENT ON COLUMN "families"."created_at" IS 'Row creation time.';--> statement-breakpoint
COMMENT ON COLUMN "families"."updated_at" IS 'Last change (trigger-maintained).';--> statement-breakpoint
COMMENT ON TABLE "travellers" IS 'The clearly separated traveller table: every person in a family (parents, children, grandparents, a nanny), listed once and attached to departures through booking_travellers. This is the ONLY table allowed to hold children''s personal data. Its sensitive columns (a child''s names, anyone''s date of birth, dietary, allergies, medical notes) are nullable and are collected only at booking, after the privacy page is updated. A row-local CHECK keeps them NULL until a booking-stage consent version is recorded on the row, so the rule also holds for edits made in NocoDB. Passports and government IDs are never stored, here or anywhere else.';--> statement-breakpoint
COMMENT ON COLUMN "travellers"."id" IS 'Primary key.';--> statement-breakpoint
COMMENT ON COLUMN "travellers"."family_id" IS 'Household this person belongs to. Deleting a family (erasure) removes its people, unless booking_travellers RESTRICT blocks it because they are on a booking.';--> statement-breakpoint
COMMENT ON COLUMN "travellers"."age_band" IS 'Current band: under_3, age_3_5, age_6_9, age_10_13, age_14_17 or adult, as the parent gave it (signup ''3–5'' maps to age_3_5). The tier for a specific trip is booking_travellers.age_band.';--> statement-breakpoint
COMMENT ON COLUMN "travellers"."label" IS 'Non-identifying display label, e.g. ''Parent: Jesse'', ''Child A (6–9)''. Lets lists and headcounts work without naming any child.';--> statement-breakpoint
COMMENT ON COLUMN "travellers"."relationship" IS 'Adults only: role in plain words, e.g. ''parent'', ''grandmother'', ''nanny''.';--> statement-breakpoint
COMMENT ON COLUMN "travellers"."first_name" IS 'Adults: allowed. CHILDREN: SENSITIVE: collect only at booking, after the privacy page is updated. Blocked by travellers_sensitive_gate_check until sensitive_consent_version is set.';--> statement-breakpoint
COMMENT ON COLUMN "travellers"."last_name" IS 'Adults: booking-stage data. CHILDREN: SENSITIVE: collect only at booking, after the privacy page is updated (same gate).';--> statement-breakpoint
COMMENT ON COLUMN "travellers"."email" IS 'Adults only (CHECK): a second adult''s email for trip messages. Always NULL for children.';--> statement-breakpoint
COMMENT ON COLUMN "travellers"."phone" IS 'Adults only (CHECK): mobile in E.164 for use during the trip. Always NULL for children.';--> statement-breakpoint
COMMENT ON COLUMN "travellers"."date_of_birth" IS 'SENSITIVE, any age: collect only at booking, after the privacy page is updated, and only if an insurer, airline or vendor requires it. age_band runs the tiers without it.';--> statement-breakpoint
COMMENT ON COLUMN "travellers"."dietary" IS 'SENSITIVE (can reveal health or religion): collect only at booking, after the privacy page is updated. What restaurants need, e.g. ''vegetarian''.';--> statement-breakpoint
COMMENT ON COLUMN "travellers"."allergies" IS 'SENSITIVE (health): collect only at booking, after the privacy page is updated. Allergen and severity, e.g. ''tree nuts, carries an EpiPen''.';--> statement-breakpoint
COMMENT ON COLUMN "travellers"."medical_notes" IS 'SENSITIVE (health): collect only at booking, after the privacy page is updated. Only what a host needs to keep this person safe (e.g. ''asthma, inhaler in backpack''). No diagnoses beyond that.';--> statement-breakpoint
COMMENT ON COLUMN "travellers"."sensitive_consent_version" IS 'Version of the booking-stage privacy notice under which a parent supplied this row''s sensitive fields. Set only by the booking form from the published notice version. Never type it by hand before that notice is live. Required by the gate CHECK before any sensitive field can be filled.';--> statement-breakpoint
COMMENT ON COLUMN "travellers"."sensitive_consent_at" IS 'When that consent was given.';--> statement-breakpoint
COMMENT ON COLUMN "travellers"."sensitive_purge_after" IS 'Date after which a scheduled job sets the sensitive fields (and a child''s names) to NULL: the departure''s ends_on + 90 days. Required by the gate CHECK whenever consent is recorded.';--> statement-breakpoint
COMMENT ON COLUMN "travellers"."created_at" IS 'Row creation time.';--> statement-breakpoint
COMMENT ON COLUMN "travellers"."updated_at" IS 'Last change (trigger-maintained).';--> statement-breakpoint
COMMENT ON TABLE "bookings" IS 'A family''s place on a departure, from waitlist or held deposit to completed trip. Holds the agreed price, terms and privacy acceptance, and the arrival and departure logistics that transfers are planned from. Money owed and paid lives in payments. Party size comes from booking_travellers and is not duplicated as counts.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."id" IS 'Primary key.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."ref" IS 'Human booking reference, unique, e.g. ''AV-0007''. Filled by a sequence so NocoDB inserts get one automatically. Quoted to families, vendors and Stripe metadata.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."family_id" IS 'The booking family. RESTRICT: a family with booking and payment history cannot be deleted. Anonymise it instead (see privacy).';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."departure_id" IS 'The departure booked. RESTRICT: cancel a departure, don''t delete it.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."status" IS 'waitlisted, held (refundable deposit, deciding), confirmed, cancelled, completed. Cancelled rows are kept.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."total_price_cents" IS 'Agreed total for this booking in minor units of currency, after any founding-family discount. NULL while only held. Balance due = this minus the net of paid payments.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."currency" IS 'Lowercase ISO 4217; normally the departure''s currency.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."held_until" IS 'End of the free-hold window (copied from reservations.hold_expires_at, or set by hand for a wired deposit).';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."terms_version" IS 'Version of the booking terms accepted, e.g. ''2027-01''.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."terms_accepted_at" IS 'When terms_version was accepted.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."privacy_version" IS 'Version of the booking-stage privacy notice the family accepted. Phone, home city, last names and arrival details are collected only once this is set.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."privacy_accepted_at" IS 'When privacy_version was accepted.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."confirmed_at" IS 'When status became confirmed.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."cancelled_at" IS 'When status became cancelled.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."cancellation_reason" IS 'Short reason, for refund decisions and learning.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."arrives_at" IS 'BOOKING STAGE: planned arrival at the destination airport or station, for transfers.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."arrival_details" IS 'BOOKING STAGE: flight or train and airport, e.g. ''IB 3456 into BIO''.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."departs_at" IS 'BOOKING STAGE: planned departure from the destination.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."departure_details" IS 'BOOKING STAGE: outbound flight or train details.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."notes" IS 'Booking notes, e.g. rooming wishes or a discount reason. No health details and no children''s names.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."created_at" IS 'Row creation time.';--> statement-breakpoint
COMMENT ON COLUMN "bookings"."updated_at" IS 'Last change (trigger-maintained).';--> statement-breakpoint
COMMENT ON TABLE "booking_travellers" IS 'Which members of the family are going on this booking, and the age tier each one joins on that departure. Headcount per tier per departure is a query on this table, and it sets how many hosts each tier needs.';--> statement-breakpoint
COMMENT ON COLUMN "booking_travellers"."id" IS 'Primary key (one simple key for spreadsheet tools).';--> statement-breakpoint
COMMENT ON COLUMN "booking_travellers"."booking_id" IS 'The booking. The roster has no meaning without it.';--> statement-breakpoint
COMMENT ON COLUMN "booking_travellers"."traveller_id" IS 'The person. RESTRICT stops a traveller on a booking from being deleted unnoticed. A trigger checks that the traveller belongs to the booking''s family.';--> statement-breakpoint
COMMENT ON COLUMN "booking_travellers"."age_band" IS 'Tier on this departure (the host group this person joins). Can differ from travellers.age_band when a birthday falls between booking and travel.';--> statement-breakpoint
COMMENT ON COLUMN "booking_travellers"."created_at" IS 'Row creation time.';--> statement-breakpoint
COMMENT ON COLUMN "booking_travellers"."updated_at" IS 'Last change (trigger-maintained).';--> statement-breakpoint
COMMENT ON TABLE "payments" IS 'The payment schedule and record for a booking: one row per amount the family owes or has paid (deposit, instalments, balance, extras), with due date, status, method and Stripe references. Refunds are tracked on the row they reverse. The deposit row links to the existing reservations row that took it, which is how a booking grows out of a Stripe deposit without touching reservations.';--> statement-breakpoint
COMMENT ON COLUMN "payments"."id" IS 'Primary key.';--> statement-breakpoint
COMMENT ON COLUMN "payments"."booking_id" IS 'The booking this money belongs to. RESTRICT: payment history is never cascaded away.';--> statement-breakpoint
COMMENT ON COLUMN "payments"."kind" IS 'deposit, instalment, balance, extra (an add-on such as an extra night).';--> statement-breakpoint
COMMENT ON COLUMN "payments"."label" IS 'Family-facing line, e.g. ''Second instalment''.';--> statement-breakpoint
COMMENT ON COLUMN "payments"."status" IS 'scheduled, invoiced (Stripe invoice or link sent), paid, refunded (fully), waived, cancelled. ''Overdue'' is derived (due_on < today and status scheduled/invoiced), not stored. A partial refund keeps status paid.';--> statement-breakpoint
COMMENT ON COLUMN "payments"."method" IS 'stripe, bank_transfer, check, other. Five-figure balances are often wired.';--> statement-breakpoint
COMMENT ON COLUMN "payments"."amount_cents" IS 'Amount due, in minor units, always positive.';--> statement-breakpoint
COMMENT ON COLUMN "payments"."currency" IS 'Lowercase ISO 4217; must match the booking''s currency (checked in the app).';--> statement-breakpoint
COMMENT ON COLUMN "payments"."due_on" IS 'Date due. For a payment taken on the spot (e.g. the Checkout deposit), the day it was taken.';--> statement-breakpoint
COMMENT ON COLUMN "payments"."paid_at" IS 'When the money cleared. Required when status is paid or refunded.';--> statement-breakpoint
COMMENT ON COLUMN "payments"."amount_refunded_cents" IS 'Total refunded against this row, between 0 and amount_cents. Net received = amount_cents − amount_refunded_cents.';--> statement-breakpoint
COMMENT ON COLUMN "payments"."refunded_at" IS 'When the latest refund was issued.';--> statement-breakpoint
COMMENT ON COLUMN "payments"."reservation_id" IS 'For kind = deposit only: the existing Stripe Checkout deposit (reservations row) that paid it. Unique, so a deposit is counted once.';--> statement-breakpoint
COMMENT ON COLUMN "payments"."stripe_checkout_session_id" IS 'Stripe Checkout Session (cs_...) when paid through Checkout.';--> statement-breakpoint
COMMENT ON COLUMN "payments"."stripe_payment_intent_id" IS 'Stripe PaymentIntent (pi_...) that settled it, unique. The webhook matches on this.';--> statement-breakpoint
COMMENT ON COLUMN "payments"."stripe_invoice_id" IS 'Stripe Invoice (in_...) when sent as a hosted invoice, unique.';--> statement-breakpoint
COMMENT ON COLUMN "payments"."notes" IS 'e.g. wire reference, ''waived: founding family'', refund reason.';--> statement-breakpoint
COMMENT ON COLUMN "payments"."created_at" IS 'Row creation time.';--> statement-breakpoint
COMMENT ON COLUMN "payments"."updated_at" IS 'Last change (trigger-maintained).';--> statement-breakpoint
COMMENT ON TABLE "vendors" IS 'Every supplier, replacing the vendor spreadsheet: houses and small hotels, age-tier hosts (freelance people are vendors too), private guides, transfer companies, restaurants and activity operators. Records type, destination, location, sourcing status, terms and Jesse''s rating. People at the vendor go in vendor_contacts. What they supply for each departure, at what rate, goes in departure_services.';--> statement-breakpoint
COMMENT ON COLUMN "vendors"."id" IS 'Primary key.';--> statement-breakpoint
COMMENT ON COLUMN "vendors"."name" IS 'Trading name, or the person''s full name for a freelance host or guide.';--> statement-breakpoint
COMMENT ON COLUMN "vendors"."category" IS 'Main type: accommodation, host, guide, transport, restaurant, activity, other. A service line can be a different category (a hotel can sell a dinner).';--> statement-breakpoint
COMMENT ON COLUMN "vendors"."is_individual" IS 'True for a private person (most hosts and guides). Their details are personal data with their own retention (see privacy).';--> statement-breakpoint
COMMENT ON COLUMN "vendors"."status" IS 'Sourcing pipeline: prospect, contacted, approved (vetted, OK to book), contracted, declined, inactive. Set inactive rather than deleting.';--> statement-breakpoint
COMMENT ON COLUMN "vendors"."journey" IS 'Destination served. NULL = not tied to one destination (e.g. an insurer).';--> statement-breakpoint
COMMENT ON COLUMN "vendors"."city" IS 'City or town where they operate.';--> statement-breakpoint
COMMENT ON COLUMN "vendors"."country_code" IS 'ISO 3166-1 alpha-2, uppercase, e.g. ''ES'', ''GT''.';--> statement-breakpoint
COMMENT ON COLUMN "vendors"."website" IS 'Website or listing URL.';--> statement-breakpoint
COMMENT ON COLUMN "vendors"."email" IS 'General business inbox (or the freelancer''s own email).';--> statement-breakpoint
COMMENT ON COLUMN "vendors"."phone" IS 'Business phone or WhatsApp in E.164.';--> statement-breakpoint
COMMENT ON COLUMN "vendors"."default_currency" IS 'Currency they quote in, lowercase ISO 4217 (''eur'', ''gtq'', ''usd''). Prefills departure_services.currency.';--> statement-breakpoint
COMMENT ON COLUMN "vendors"."payment_terms" IS 'e.g. ''30% on signing, balance 30 days before arrival''; how to pay them.';--> statement-breakpoint
COMMENT ON COLUMN "vendors"."rating" IS 'Jesse''s 1–5 judgement after a site visit or a trip.';--> statement-breakpoint
COMMENT ON COLUMN "vendors"."notes" IS 'Quality notes, what to watch for.';--> statement-breakpoint
COMMENT ON COLUMN "vendors"."created_at" IS 'Row creation time.';--> statement-breakpoint
COMMENT ON COLUMN "vendors"."updated_at" IS 'Last change (trigger-maintained).';--> statement-breakpoint
COMMENT ON TABLE "vendor_contacts" IS 'People at a vendor: the owner, the reservations desk, the on-the-day driver. Kept separate because one vendor has several and roles matter during trip week. Optional for a freelancer whose vendor row is the person.';--> statement-breakpoint
COMMENT ON COLUMN "vendor_contacts"."id" IS 'Primary key.';--> statement-breakpoint
COMMENT ON COLUMN "vendor_contacts"."vendor_id" IS 'The vendor. Contacts go with it.';--> statement-breakpoint
COMMENT ON COLUMN "vendor_contacts"."name" IS 'Person''s name.';--> statement-breakpoint
COMMENT ON COLUMN "vendor_contacts"."role" IS 'e.g. ''Owner'', ''Reservations'', ''Driver dispatch''.';--> statement-breakpoint
COMMENT ON COLUMN "vendor_contacts"."email" IS 'Work email.';--> statement-breakpoint
COMMENT ON COLUMN "vendor_contacts"."phone" IS 'Work phone, E.164.';--> statement-breakpoint
COMMENT ON COLUMN "vendor_contacts"."prefers_whatsapp" IS 'Reach them on WhatsApp first.';--> statement-breakpoint
COMMENT ON COLUMN "vendor_contacts"."language" IS 'Preferred language, e.g. ''es'', ''en'', ''eu''.';--> statement-breakpoint
COMMENT ON COLUMN "vendor_contacts"."is_primary" IS 'The main contact. At most one per vendor.';--> statement-breakpoint
COMMENT ON COLUMN "vendor_contacts"."notes" IS 'Working notes, e.g. best hours to call.';--> statement-breakpoint
COMMENT ON COLUMN "vendor_contacts"."created_at" IS 'Row creation time.';--> statement-breakpoint
COMMENT ON COLUMN "vendor_contacts"."updated_at" IS 'Last change (trigger-maintained).';--> statement-breakpoint
COMMENT ON TABLE "departure_services" IS 'The departure''s costed supplier sheet: each thing a departure needs (the house for nine nights, a host for the 6–9s, the arrival transfer, a dinner, a surf lesson), with the vendor, the rate and unit in the vendor''s currency, the quote and booking status, the vendor''s due dates and what has been paid. A row can exist before a vendor is chosen (status needed).';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."id" IS 'Primary key.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."departure_id" IS 'The departure this service is for.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."vendor_id" IS 'Supplier. NULL = slot not yet sourced (status needed or cancelled only). RESTRICT keeps cost history; set the vendor inactive instead.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."category" IS 'What this line buys (same enum as vendors.category).';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."title" IS 'Short line, e.g. ''Villa Miramar, 5 bedrooms, 9 nights'' or ''Day 4 surf lesson, Zurriola''.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."description" IS 'Detail and inclusions.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."age_band" IS 'Tier served, when the line is for one tier (hosts, tier activities). NULL = everyone or several tiers (say which in title).';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."starts_on" IS 'First date of the service, local date. NULL until fixed.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."ends_on" IS 'Last date. NULL or equal to starts_on for a single day.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."start_time" IS 'Local start time (transfers, activities).';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."status" IS 'needed, requested, quoted, held, confirmed, declined, cancelled.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."rate_unit" IS 'What unit_rate_cents is per: flat, per_person, per_family, per_night, per_room_night, per_hour, per_day.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."unit_rate_cents" IS 'Quoted rate per unit in the vendor''s currency, minor units (cents, centavos). NULL until quoted.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."quantity" IS 'Number of units, e.g. 36 room-nights, 8.5 hours, 42 people.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."currency" IS 'Lowercase ISO 4217 of the quote (''eur'', ''gtq'', ''usd''). Prefilled from vendors.default_currency.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."total_cents" IS 'Computed total in the vendor''s currency. Read-only (generated).';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."usd_estimate_cents" IS 'Jesse''s USD estimate at a planning exchange rate, for margin roll-ups per departure. Set by hand.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."quote_valid_until" IS 'Quote or hold expiry; chase before this date.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."confirmation_ref" IS 'Vendor''s booking or confirmation number.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."deposit_due_on" IS 'When Avelune owes the vendor its deposit.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."balance_due_on" IS 'When Avelune owes the vendor the balance.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."paid_cents" IS 'Paid to the vendor so far, same currency, kept by hand (there is no vendor payments ledger yet).';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."cancellation_terms" IS 'The vendor''s cancellation and refund terms, for exposure planning.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."notes" IS 'Logistics. No children''s names or health details; hosts get those from the rooming and care sheets.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."created_at" IS 'Row creation time.';--> statement-breakpoint
COMMENT ON COLUMN "departure_services"."updated_at" IS 'Last change (trigger-maintained).';--> statement-breakpoint
COMMENT ON TABLE "documents" IS 'Links (never files) to contracts, quotes, invoices, insurance certificates, licences, host background checks, signed booking terms and waivers, with status and expiry. For a children''s programme that promises background-checked hosts, the key query is ''what lapses before the departure ends''. Uses explicit nullable foreign keys, at least one set, with no polymorphic type/id pair.';--> statement-breakpoint
COMMENT ON COLUMN "documents"."id" IS 'Primary key.';--> statement-breakpoint
COMMENT ON COLUMN "documents"."title" IS 'e.g. ''Hotel Arbaso group contract 2027'', ''Background check: M. Etxeberria''.';--> statement-breakpoint
COMMENT ON COLUMN "documents"."kind" IS 'contract, quote, invoice, insurance, licence, background_check, waiver, terms, other.';--> statement-breakpoint
COMMENT ON COLUMN "documents"."status" IS 'requested, draft, sent, on_file, void. ''Expired'' is derived from expires_on, not stored.';--> statement-breakpoint
COMMENT ON COLUMN "documents"."url" IS 'https link to the file in Drive, Dropbox, DocuSign or Stripe. Access control lives there. Required once sent or on_file. Never link a medical form or a passport scan.';--> statement-breakpoint
COMMENT ON COLUMN "documents"."vendor_id" IS 'Vendor it belongs to (contract, insurance, licence, background check).';--> statement-breakpoint
COMMENT ON COLUMN "documents"."departure_service_id" IS 'The specific service line a quote or confirmation is for. Goes with the line.';--> statement-breakpoint
COMMENT ON COLUMN "documents"."departure_id" IS 'Departure-wide document (run sheet, group insurance).';--> statement-breakpoint
COMMENT ON COLUMN "documents"."booking_id" IS 'Customer document (signed terms, waiver).';--> statement-breakpoint
COMMENT ON COLUMN "documents"."dated_on" IS 'Date signed or issued.';--> statement-breakpoint
COMMENT ON COLUMN "documents"."expires_on" IS 'Expiry. Insurance and background checks must cover the departure''s ends_on; the admin view flags any that do not.';--> statement-breakpoint
COMMENT ON COLUMN "documents"."notes" IS 'Working notes. Never the content of a background check.';--> statement-breakpoint
COMMENT ON COLUMN "documents"."created_at" IS 'Row creation time.';--> statement-breakpoint
COMMENT ON COLUMN "documents"."updated_at" IS 'Last change (trigger-maintained).';--> statement-breakpoint
COMMENT ON TABLE "interactions" IS 'A dated log of emails, calls, meetings, messages and notes with a family or vendor or about a departure, with an optional follow-up date. Answers ''what was last said to whom'', and its open follow-ups are Jesse''s to-do list (this replaces a separate tasks table).';--> statement-breakpoint
COMMENT ON COLUMN "interactions"."id" IS 'Primary key.';--> statement-breakpoint
COMMENT ON COLUMN "interactions"."family_id" IS 'Family it concerns. Erasing a family erases its log.';--> statement-breakpoint
COMMENT ON COLUMN "interactions"."vendor_id" IS 'Vendor it concerns.';--> statement-breakpoint
COMMENT ON COLUMN "interactions"."departure_id" IS 'Departure it concerns (only empty planning departures can be deleted, so this rarely fires).';--> statement-breakpoint
COMMENT ON COLUMN "interactions"."kind" IS 'email, call, video, meeting, message (WhatsApp/SMS), note (internal, or a pure to-do).';--> statement-breakpoint
COMMENT ON COLUMN "interactions"."occurred_at" IS 'When it happened.';--> statement-breakpoint
COMMENT ON COLUMN "interactions"."summary" IS 'What was said or decided, a sentence or two, not a transcript. No health details, children''s names or passport numbers; for those, record only that they were sent, e.g. ''passport details sent to hotel directly''.';--> statement-breakpoint
COMMENT ON COLUMN "interactions"."follow_up_on" IS 'Date to act again, if any.';--> statement-breakpoint
COMMENT ON COLUMN "interactions"."follow_up_done_at" IS 'When the follow-up was done. NULL with a follow_up_on date = still open.';--> statement-breakpoint
COMMENT ON COLUMN "interactions"."created_at" IS 'Row creation time.';--> statement-breakpoint
COMMENT ON COLUMN "interactions"."updated_at" IS 'Last change (trigger-maintained).';--> statement-breakpoint
COMMENT ON TABLE "signups" IS 'Early-access requests from the website (stage 1). One row per email address. App-owned: written by the signup and enrich forms; treat as read-only in a spreadsheet tool. Also the marketing-consent record: a family promoted from here keeps this row.';--> statement-breakpoint
COMMENT ON COLUMN "signups"."id" IS 'Primary key.';--> statement-breakpoint
COMMENT ON COLUMN "signups"."email" IS 'Email as typed, trimmed.';--> statement-breakpoint
COMMENT ON COLUMN "signups"."email_key" IS 'Lowercased and trimmed email; the dedupe key (unique).';--> statement-breakpoint
COMMENT ON COLUMN "signups"."name" IS 'First name, optional.';--> statement-breakpoint
COMMENT ON COLUMN "signups"."children_count" IS 'Number of children, optional.';--> statement-breakpoint
COMMENT ON COLUMN "signups"."children_ages" IS 'Children''s ages or bands as the parent typed them (free text, up to 120 characters), never names. The privacy page promises bands only.';--> statement-breakpoint
COMMENT ON COLUMN "signups"."destinations" IS 'Destinations of interest (array of journey slugs).';--> statement-breakpoint
COMMENT ON COLUMN "signups"."notes" IS 'Free-text note from the enrich form. Do not copy into other tables without checking for health details.';--> statement-breakpoint
COMMENT ON COLUMN "signups"."source" IS 'Short slug for where on the site the signup came from (e.g. ''hero'').';--> statement-breakpoint
COMMENT ON COLUMN "signups"."referrer" IS 'HTTP referrer at signup, if any.';--> statement-breakpoint
COMMENT ON COLUMN "signups"."utm" IS 'UTM parameters at signup (json).';--> statement-breakpoint
COMMENT ON COLUMN "signups"."landing_path" IS 'Page path the visitor landed on.';--> statement-breakpoint
COMMENT ON COLUMN "signups"."status" IS 'pending (not confirmed), confirmed, unsubscribed.';--> statement-breakpoint
COMMENT ON COLUMN "signups"."confirm_token" IS 'SECRET capability token that unlocks the enrich form. Never expose or share this column.';--> statement-breakpoint
COMMENT ON COLUMN "signups"."consent_at" IS 'When the privacy consent was given.';--> statement-breakpoint
COMMENT ON COLUMN "signups"."consent_version" IS 'Version of the privacy notice consented to.';--> statement-breakpoint
COMMENT ON COLUMN "signups"."confirmed_at" IS 'When the email address was confirmed.';--> statement-breakpoint
COMMENT ON COLUMN "signups"."ip_hash" IS 'Hash of the IP address at signup. The raw IP is never stored.';--> statement-breakpoint
COMMENT ON COLUMN "signups"."user_agent" IS 'Browser user agent at signup.';--> statement-breakpoint
COMMENT ON COLUMN "signups"."created_at" IS 'Row creation time.';--> statement-breakpoint
COMMENT ON COLUMN "signups"."updated_at" IS 'Last change (set by the app).';--> statement-breakpoint
COMMENT ON TABLE "reservations" IS 'Refundable deposit holds taken through Stripe Checkout (stage 2). App-owned and written by the checkout route and the Stripe webhook; treat as read-only in a spreadsheet tool. A paid reservation is linked to a booking through payments.reservation_id.';--> statement-breakpoint
COMMENT ON COLUMN "reservations"."id" IS 'Primary key.';--> statement-breakpoint
COMMENT ON COLUMN "reservations"."signup_id" IS 'The signup this deposit came from, if any. SET NULL on signup deletion.';--> statement-breakpoint
COMMENT ON COLUMN "reservations"."email" IS 'Email as typed at checkout.';--> statement-breakpoint
COMMENT ON COLUMN "reservations"."email_key" IS 'Lowercased and trimmed email.';--> statement-breakpoint
COMMENT ON COLUMN "reservations"."journey" IS 'Which journey the deposit holds a place on.';--> statement-breakpoint
COMMENT ON COLUMN "reservations"."amount_cents" IS 'Deposit amount in minor units.';--> statement-breakpoint
COMMENT ON COLUMN "reservations"."currency" IS 'Lowercase ISO 4217.';--> statement-breakpoint
COMMENT ON COLUMN "reservations"."status" IS 'pending, paid, refunded, expired, cancelled.';--> statement-breakpoint
COMMENT ON COLUMN "reservations"."stripe_checkout_session_id" IS 'Stripe Checkout Session id (cs_...), unique.';--> statement-breakpoint
COMMENT ON COLUMN "reservations"."stripe_payment_intent_id" IS 'Stripe PaymentIntent id (pi_...).';--> statement-breakpoint
COMMENT ON COLUMN "reservations"."stripe_customer_id" IS 'Stripe Customer id (cus_...), when Checkout created one.';--> statement-breakpoint
COMMENT ON COLUMN "reservations"."hold_expires_at" IS 'End of the free-hold window.';--> statement-breakpoint
COMMENT ON COLUMN "reservations"."paid_at" IS 'When the payment cleared.';--> statement-breakpoint
COMMENT ON COLUMN "reservations"."refunded_at" IS 'When the deposit was refunded.';--> statement-breakpoint
COMMENT ON COLUMN "reservations"."created_at" IS 'Row creation time.';--> statement-breakpoint
COMMENT ON COLUMN "reservations"."updated_at" IS 'Last change (set by the app).';--> statement-breakpoint
COMMENT ON TABLE "stripe_events" IS 'Stripe event ids already handled; the webhook''s idempotency gate. App-owned; never edit.';--> statement-breakpoint
COMMENT ON COLUMN "stripe_events"."id" IS 'Stripe event id (evt_...).';--> statement-breakpoint
COMMENT ON COLUMN "stripe_events"."type" IS 'Stripe event type, e.g. checkout.session.completed.';--> statement-breakpoint
COMMENT ON COLUMN "stripe_events"."received_at" IS 'When the event was first handled.';--> statement-breakpoint
COMMENT ON SEQUENCE "booking_ref_seq" IS 'Source of bookings.ref (''AV-0001'', ''AV-0002'', ...). Gaps are normal.';--> statement-breakpoint
CREATE FUNCTION "public"."set_updated_at"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	NEW.updated_at := now();
	RETURN NEW;
END;
$$;--> statement-breakpoint
COMMENT ON FUNCTION "public"."set_updated_at"() IS 'BEFORE UPDATE trigger: stamps updated_at so edits made in NocoDB or psql count too (Drizzle''s $onUpdate only runs in the app).';--> statement-breakpoint
CREATE TRIGGER "departures_set_updated_at" BEFORE UPDATE ON "public"."departures" FOR EACH ROW EXECUTE FUNCTION "public"."set_updated_at"();--> statement-breakpoint
CREATE TRIGGER "families_set_updated_at" BEFORE UPDATE ON "public"."families" FOR EACH ROW EXECUTE FUNCTION "public"."set_updated_at"();--> statement-breakpoint
CREATE TRIGGER "travellers_set_updated_at" BEFORE UPDATE ON "public"."travellers" FOR EACH ROW EXECUTE FUNCTION "public"."set_updated_at"();--> statement-breakpoint
CREATE TRIGGER "bookings_set_updated_at" BEFORE UPDATE ON "public"."bookings" FOR EACH ROW EXECUTE FUNCTION "public"."set_updated_at"();--> statement-breakpoint
CREATE TRIGGER "booking_travellers_set_updated_at" BEFORE UPDATE ON "public"."booking_travellers" FOR EACH ROW EXECUTE FUNCTION "public"."set_updated_at"();--> statement-breakpoint
CREATE TRIGGER "payments_set_updated_at" BEFORE UPDATE ON "public"."payments" FOR EACH ROW EXECUTE FUNCTION "public"."set_updated_at"();--> statement-breakpoint
CREATE TRIGGER "vendors_set_updated_at" BEFORE UPDATE ON "public"."vendors" FOR EACH ROW EXECUTE FUNCTION "public"."set_updated_at"();--> statement-breakpoint
CREATE TRIGGER "vendor_contacts_set_updated_at" BEFORE UPDATE ON "public"."vendor_contacts" FOR EACH ROW EXECUTE FUNCTION "public"."set_updated_at"();--> statement-breakpoint
CREATE TRIGGER "departure_services_set_updated_at" BEFORE UPDATE ON "public"."departure_services" FOR EACH ROW EXECUTE FUNCTION "public"."set_updated_at"();--> statement-breakpoint
CREATE TRIGGER "documents_set_updated_at" BEFORE UPDATE ON "public"."documents" FOR EACH ROW EXECUTE FUNCTION "public"."set_updated_at"();--> statement-breakpoint
CREATE TRIGGER "interactions_set_updated_at" BEFORE UPDATE ON "public"."interactions" FOR EACH ROW EXECUTE FUNCTION "public"."set_updated_at"();--> statement-breakpoint
CREATE FUNCTION "public"."booking_travellers_check_same_family"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	IF (SELECT t.family_id FROM "public"."travellers" t WHERE t.id = NEW.traveller_id)
		IS DISTINCT FROM (SELECT b.family_id FROM "public"."bookings" b WHERE b.id = NEW.booking_id) THEN
		RAISE EXCEPTION 'traveller % does not belong to the family of booking %', NEW.traveller_id, NEW.booking_id
			USING ERRCODE = 'check_violation';
	END IF;
	RETURN NEW;
END;
$$;--> statement-breakpoint
COMMENT ON FUNCTION "public"."booking_travellers_check_same_family"() IS 'Trigger function: a traveller can only be put on a booking of their own family.';--> statement-breakpoint
CREATE TRIGGER "booking_travellers_same_family" BEFORE INSERT OR UPDATE OF booking_id, traveller_id ON "public"."booking_travellers" FOR EACH ROW EXECUTE FUNCTION "public"."booking_travellers_check_same_family"();
